export type Tone = "Default" | "Strong" | "Muted" | "Faint" | "Primary" | "Success" | "Warning" | "Danger" | "Info" | "Live" | "Red" | "Orange" | "Amber" | "Yellow" | "Lime" | "Green" | "Emerald" | "Teal" | "Cyan" | "Sky" | "Blue" | "Indigo" | "Violet" | "Purple" | "Fuchsia" | "Pink" | "Rose" | "Gold" | "Slate"

export type TransformCond = "Always" | { Not: TransformCond } | { And: TransformCond[] } | { Or: TransformCond[] } | { Exists: { path: string } } | { Equals: { path: string; value: JsonValue } } | { ListNotEmpty: { path: string } } | { EqualsPath: { left: string; right: string } }

export type TransformOp = { When: { cond: TransformCond; ops: TransformOp[]; else_ops: TransformOp[] } } | { Set: { path: string; value: JsonValue } } | { Remove: { path: string } } | { MergeObject: { path: string; value: Partial<{ [key in string]: JsonValue }> } } | { Append: { path: string; value: JsonValue } } | { AppendUnique: { path: string; value: JsonValue } } | { FilterArray: { path: string; as_key: string; predicate: TransformCond } } | { MapArray: { path: string; as_key: string; template: JsonValue } } | { Copy: { from: string; to: string } } | { Move: { from: string; to: string } } | { EmitRunServerAction: { action_id: string; input_map: Partial<{ [key in string]: string }> | null; reconcile_node: boolean } } | "EmitCancel" | "EmitNextNode" | "EmitPreviousNode"

/**
 * The typeface a page marks with `themed` text uses: the app's own,
 * a tall condensed one for sports and lobbies, or a spooky one for Midnight.
 */
export type Typeface = "Default" | "Condensed" | "Spooky"

export type UserResource = { id: string; username: string; display_name: string; avatar_url: string; db_score: number; is_bot?: boolean }

export type WorkflowAction = { id: string; action_type: ActionType; allow_while_loading: boolean; target: string | null; progress_node: boolean }

export type WorkflowDefinition = { id: string; owner_id: string | null; starting_server_action: string | null; name: string; description: string | null; responses: Partial<{ [key in string]: JsonValue }>; context: Partial<{ [key in string]: JsonValue }>; nodes: Partial<{ [key in string]: { title: string; description: string | null; visuals: WorkflowVisual[]; condition: NodeCondition | null; parent_id: string | null } }>; actions: WorkflowAction[]; 
/**
 * See `CreateWorkflowDefinition::multi_instance_per_user`. Mirrors that
 * flag through the catalog so the manager can read it during
 * dedupe / resume decisions.
 */
multi_instance_per_user?: boolean }

export type WorkflowDisplay = { type: DisplayType; 
/**
 * A name animations find this display by, as `[data-mark~="name"]`.
 * Takes `{key}` templates and several names separated by spaces.
 */
mark?: string | null }

export type WorkflowInput = { readonly: NodeCondition | null; type: InputType; default_value: JsonValue | null; required: boolean; on_change_action: [string, Partial<{ [key in string]: string }>] | null }

export type WorkflowNode = { title: string; description: string | null; visuals: WorkflowVisual[]; condition: NodeCondition | null; parent_id: string | null }

export type WorkflowPredicate = { ByWorkflowDefinitionIdAndUserId: [string, string] } | { And: WorkflowPredicate[] } | { Or: WorkflowPredicate[] }

export type WorkflowResource = { inject: InjectWorkflowPlace | null; instance_id: string; workflow_id: string; stale_definition: boolean; name: string; description: string | null; responses: Partial<{ [key in string]: JsonValue }>; completed: boolean; status: WorkflowRuntimeStatus; complete_message: string | null; visuals: WorkflowVisual[]; user_id: string; current_node_id: string; waiting: boolean; attached_workflows: Partial<{ [key in string]: AttachedWorkflowMeta }>; parent: string | null; created_at: string; updated_at: string; completed_at: string | null }

export type WorkflowResourceWithContext = { workflow: WorkflowResource; context: Partial<{ [key in string]: JsonValue }> }

export type WorkflowRuntimeStatus = "active" | "waiting" | "completed" | "cancelled" | "failed"

